export interface PhetSim {
  slug: string;           // URL slug (mevcut: 'atom-olustur', yeni: 'faraday-kanunu')
  phet_id: string;        // PhET orijinal ID: 'build-an-atom'
  title_tr: string;       // Türkçe başlık
  description: string;
  category: 'TYT' | 'AYT' | 'TYT/AYT';
  subject: 'Fizik' | 'Kimya' | 'Biyoloji' | 'Matematik' | 'Genel';
  topic: string;
  difficulty_level: 1 | 2 | 3 | 4 | 5;
  related_yks_topics: string[];
  badge?: string;
  has_turkish: boolean;   // locale=tr çalışıyor mu
  is_active: boolean;
}

// PhET URL yardımcısı
export function getPhetUrl(phet_id: string, has_turkish: boolean): string {
  const locale = has_turkish ? '?locale=tr' : '';
  return `https://phet.colorado.edu/sims/html/${phet_id}/latest/${phet_id}_all.html${locale}`;
}

