// Slug'a göre simülasyon bul
export function findSimBySlug(slug: string): PhetSim | undefined {
  return PHET_REGISTRY.find(s => s.slug === slug);
}

// Kategoriye göre filtrele
export function filterPhetSims(params: {
  category?: string;
  subject?: string;
  difficulty?: number;
  search?: string;
}): PhetSim[] {
  let sims = [...PHET_REGISTRY];
  if (params.category && params.category !== 'Tümü') {
    sims = sims.filter(s => s.category === params.category || s.category === 'TYT/AYT');
  }
  if (params.subject && params.subject !== 'Tümü') {
    sims = sims.filter(s => s.subject === params.subject);
  }
  if (params.difficulty && params.difficulty !== 0) {
    sims = sims.filter(s => s.difficulty_level === params.difficulty);
  }
  if (params.search && params.search.trim()) {
    const q = params.search.trim().toLowerCase();
    sims = sims.filter(s =>
      s.title_tr.toLowerCase().includes(q) ||
      s.description.toLowerCase().includes(q) ||
      s.topic.toLowerCase().includes(q) ||
      s.related_yks_topics.some(t => t.toLowerCase().includes(q))
    );
  }
  return sims;
}
